<?php
namespace Tests;
use App\Services\SalonStore;
use Illuminate\Foundation\Testing\TestCase;
use Illuminate\Support\Facades\{Artisan,DB,Cache};
final class ProviderDirectoryTest extends TestCase
{
 public function createApplication(){$a=require __DIR__.'/../bootstrap/app.php';$a->make(\Illuminate\Contracts\Console\Kernel::class)->bootstrap();return $a;}
 protected function setUp():void{parent::setUp();if(config('database.default')!=='sqlite'&&!str_ends_with((string)config('database.connections.mysql.database'),'_test'))throw new \RuntimeException('Külön tesztadatbázis szükséges.');Artisan::call('migrate',['--force'=>true]);DB::table('salon_state')->delete();DB::table('providers')->delete();Cache::flush();$s=SalonStore::initial();$s['settings']['providerEmail']='private@example.com';$s['clients']=[['id'=>'secret','name'=>'Titkos Vendég','email'=>'guest@example.com']];$s['profile']=['address'=>'Budapest, Minta utca 1.','phone'=>'06301234567'];DB::table('salon_state')->insert(['id'=>1,'data'=>json_encode($s)]);}
 public function test_public_directory_exposes_only_public_fields_and_searches_catalog():void{$r=$this->getJson('/api/providers?q=Budapest')->assertOk()->assertJsonPath('total',1)->assertJsonPath('items.0.url','/foglalas?provider=1');$this->assertSame(['id','name','profession','city','address','logo','cover','categories','services','minPrice','reviewCount','rating','url'],array_keys($r->json('items.0')));$this->assertStringNotContainsString('private@example.com',$r->getContent());$this->assertStringNotContainsString('Titkos Vendég',$r->getContent());$this->getJson('/api/providers?q=hajfestés')->assertJsonPath('total',1);$this->getJson('/api/providers?q=harmonia')->assertJsonPath('total',1);$this->getJson('/api/providers?q=nemletezik')->assertJsonPath('total',0);$this->getJson('/api/platform/providers')->assertUnauthorized();$this->withSession(['admin'=>true,'provider_id'=>2]);$this->getJson('/api/providers?provider=1')->assertOk();}
 public function test_directory_paginates_and_omits_empty_or_archived_catalogs():void{$s=SalonStore::initial();for($i=2;$i<=26;$i++){DB::table('providers')->insert(['id'=>$i,'name'=>'Teszt','email'=>'p'.$i.'@example.com','password_hash'=>'test-only','active'=>true,'trial_started_at'=>now(),'trial_ends_at'=>now()->addMonths(2),'created_at'=>now(),'updated_at'=>now()]);DB::table('salon_state')->insert(['id'=>$i,'data'=>json_encode($s)]);}$empty=$s;$empty['services']=[];DB::table('salon_state')->insert(['id'=>27,'data'=>json_encode($empty)]);$archived=$s;foreach($archived['services'] as &$v)$v['archived']=true;unset($v);DB::table('salon_state')->insert(['id'=>28,'data'=>json_encode($archived)]);$this->getJson('/api/providers')->assertJsonCount(24,'items')->assertJsonPath('total',26)->assertJsonPath('pages',2);$this->getJson('/api/providers?page=2')->assertJsonCount(2,'items')->assertJsonPath('items.0.id',25);$this->getJson('/api/providers?page=0')->assertUnprocessable();$this->getJson('/api/providers?q='.str_repeat('a',101))->assertUnprocessable();}
 public function test_public_routes_serve_navigation_without_private_session():void{foreach(['/','/szolgaltatok','/szolgaltato','/arak','/kapcsolat','/foglalas','/fiokom'] as $path)$this->get($path)->assertOk()->assertSee('Felső menü')->assertSee('/navigation.js',false);}

 public function test_disabled_or_unconfigured_provider_is_not_advertised():void{$s=SalonStore::initial();foreach([2,3,4] as $id){DB::table('providers')->insert(['id'=>$id,'name'=>'Teszt','email'=>'p'.$id.'@example.com','password_hash'=>'test-only','active'=>$id!==2,'trial_started_at'=>now(),'trial_ends_at'=>now()->addMonths(2),'created_at'=>now(),'updated_at'=>now()]);$data=$s;if($id===3)$data['services']=[];if($id===4)foreach($data['services'] as &$service)$service['archived']=true;unset($service);DB::table('salon_state')->insert(['id'=>$id,'data'=>json_encode($data)]);}$this->getJson('/api/providers')->assertJsonPath('total',1)->assertJsonCount(1,'items');}

 public function test_solo_directory_ignores_the_old_team_assignments():void{$s=SalonStore::initial();$s['settings']['businessMode']='solo';$s['settings']['primaryStaffId']='eszter';DB::table('salon_state')->where('id',1)->update(['data'=>json_encode($s)]);$r=$this->getJson('/api/providers?q=masszazs')->assertOk()->assertJsonPath('total',1);$this->assertContains('Frissítő masszázs',$r->json('items.0.services'));$this->getJson('/api/providers?q=hajfestes')->assertJsonPath('total',1);}
}
